CREATE TABLE aux_capture_imports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,capture_hash CHAR(64) NOT NULL UNIQUE,source_pins JSON NOT NULL,table_inventory JSON NOT NULL,archive_path VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE aux_capture_records(capture_id BIGINT UNSIGNED NOT NULL,source_table VARCHAR(100) NOT NULL,source_id VARCHAR(100) NOT NULL,source_ordinal BIGINT UNSIGNED NOT NULL,row_sha256 CHAR(64) NOT NULL,raw_evidence JSON NOT NULL,PRIMARY KEY(capture_id,source_table,source_id),FOREIGN KEY(capture_id) REFERENCES aux_capture_imports(id)) ENGINE=InnoDB;
CREATE TABLE aux_capture_bindings(source_table VARCHAR(100) NOT NULL,source_id VARCHAR(100) NOT NULL,target_table VARCHAR(100) NOT NULL,target_id BIGINT UNSIGNED NOT NULL,capture_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(source_table,source_id),FOREIGN KEY(capture_id) REFERENCES aux_capture_imports(id)) ENGINE=InnoDB;
ALTER TABLE aux_premises ADD source_created_at DATETIME(6) NULL,ADD source_updated_at DATETIME(6) NULL;
CREATE TABLE aux_confirmed_premises(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,stable_id VARCHAR(30) NOT NULL UNIQUE,kind VARCHAR(40) NOT NULL,floor VARCHAR(50) NOT NULL,designation VARCHAR(200) NOT NULL,area DECIMAL(14,3) NULL,area_variants TEXT NOT NULL,cadastral_number TEXT NOT NULL,aliases TEXT NOT NULL,source_ids JSON NOT NULL,source_rows TEXT NOT NULL,decision TEXT NOT NULL,questions TEXT NOT NULL,has_questions TINYINT NOT NULL,disputed_columns JSON NOT NULL,source_sha256 CHAR(64) NOT NULL,source_cards JSON NOT NULL,revision INT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE aux_owner_evidence(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,evidence_key VARCHAR(100) NOT NULL UNIQUE,received_on DATE NOT NULL,sequence_number INT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,payload JSON NOT NULL,source_created_at DATETIME(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE aux_owner_cadastral_objects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(100) NOT NULL UNIQUE,level VARCHAR(40) NOT NULL,floor VARCHAR(50) NOT NULL,source_positions JSON NOT NULL,evidence_id BIGINT UNSIGNED NOT NULL,FOREIGN KEY(evidence_id) REFERENCES aux_owner_evidence(id)) ENGINE=InnoDB;
CREATE TABLE aux_owner_units(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,premise_id BIGINT UNSIGNED NOT NULL UNIQUE,canonical_premise_id BIGINT UNSIGNED NULL,role VARCHAR(40) NOT NULL,ownership VARCHAR(40) NOT NULL,sale_date DATE NULL,cadastral_object_id BIGINT UNSIGNED NULL,legal_unit_key VARCHAR(100) NOT NULL,aliases JSON NOT NULL,notes TEXT NOT NULL,evidence_id BIGINT UNSIGNED NOT NULL,FOREIGN KEY(premise_id) REFERENCES aux_confirmed_premises(id),FOREIGN KEY(canonical_premise_id) REFERENCES aux_confirmed_premises(id),FOREIGN KEY(cadastral_object_id) REFERENCES aux_owner_cadastral_objects(id),FOREIGN KEY(evidence_id) REFERENCES aux_owner_evidence(id)) ENGINE=InnoDB;
CREATE TABLE aux_owner_changes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,premise_id BIGINT UNSIGNED NOT NULL,evidence_id BIGINT UNSIGNED NOT NULL,field VARCHAR(80) NOT NULL,before_value JSON NOT NULL,after_value JSON NOT NULL,UNIQUE(premise_id,evidence_id,field),FOREIGN KEY(premise_id) REFERENCES aux_confirmed_premises(id),FOREIGN KEY(evidence_id) REFERENCES aux_owner_evidence(id)) ENGINE=InnoDB;
